import {recipes,layer} from './ingredients.js';
// Single source of truth (choosing another product or adding to the cart starts the card over; the cart stays): { product: Receita id, editing, removed: applied ids, draft: ids in the open editor, combo, drink: Bebida do combo ('' until chosen; only with the combo), drinkError: the combo was added without a drink, qty: Quantidade (1-99), cart: Items, each with its unit price }.
// The card's default (on load, on choosing another burger and after adding): no combo, no drink, Quantidade 1, no Personalização.
const fresh={removed:[],draft:[],editing:false,combo:false,drink:'',drinkError:false,qty:1};
export const initial={product:'whopper',...fresh,cart:[]};
/** Same Item: product, Personalização, combo and drink; it then adds to the quantity already in the cart. */
const same=(a,b)=>a.product===b.product&&a.combo===b.combo&&a.drink===b.drink&&[...a.removed].sort().join()===[...b.removed].sort().join();
export function reducer(s,a){switch(a.type){case'select':return s.product===a.product||!recipes[a.product]?s:{...s,...fresh,product:a.product};case'open':return {...s,editing:true,draft:[...s.removed]};case'toggle':if(!s.editing||layer(recipes[s.product],a.id)?.locked)return s;return {...s,draft:s.draft.includes(a.id)?s.draft.filter(x=>x!==a.id):[...s.draft,a.id]};case'remove':return s.draft.includes(a.id)?s:reducer(s,{type:'toggle',id:a.id});case'reset':return {...s,draft:[]};case'apply':return {...s,editing:false,removed:[...s.draft]};case'cancel':return {...s,editing:false,draft:[]};case'combo':return {...s,combo:a.value,drink:a.value?s.drink:'',drinkError:false};case'qty':return {...s,qty:Math.max(1,Math.min(99,a.value))};case'drink':return s.combo?{...s,drink:a.value,drinkError:false}:s;case'add':if(s.combo&&!s.drink)return {...s,drinkError:true};{const item={product:s.product,removed:[...s.removed],combo:s.combo,drink:s.drink,qty:s.qty,price:price(s)},i=s.cart.findIndex(c=>same(c,item));return {...s,...fresh,cart:i<0?[...s.cart,item]:s.cart.map((c,j)=>j===i?{...c,qty:c.qty+item.qty}:c)}}case'delete':return {...s,cart:s.cart.filter((_,i)=>i!==a.index)};default:return s}}
export const comboFee=1200,drinks=['Coca-Cola','Coca-Cola Zero','Sprite','Fanta Laranja','Natural One Laranja','Natural One Uva','Água de Copo'],money=n=>(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),price=s=>recipes[s.product].price+(s.combo?comboFee:0);
